function renderWorlds() {
  const el = document.getElementById('worldsGrid');
  el.innerHTML = WORLDS.map(w => `
    <div class="bg-white dark:bg-slate-800 rounded-2xl shadow-lg card-lift cursor-pointer border border-slate-100 dark:border-slate-700 overflow-hidden group"
         style="border-top: 4px solid ${w.border};"
         role="button" tabindex="0" aria-label="Explore ${w.name}" onclick="openWorldInPlayer(${w.num})">
      <div class="p-5">
        <!-- Top row: icon + badge -->
        <div class="flex items-start gap-3 mb-4">
          <div class="w-14 h-14 rounded-2xl bg-gradient-to-br ${w.color} flex items-center justify-center text-3xl shadow-md flex-shrink-0 group-hover:scale-110 transition-transform duration-300">
            ${w.emoji}
          </div>
          <div class="flex-1 min-w-0">
            <span class="inline-block text-white font-bold text-xs px-3 py-1 rounded-full mb-2" style="background:${w.badge};">World ${w.num}</span><span style="margin-left:6px;background:#22C55E;color:#fff;font-size:.65rem;font-weight:800;padding:2px 7px;border-radius:999px;">▶ LIVE</span>
            <h3 class="font-display font-extrabold text-lg text-slate-800 dark:text-white leading-tight">${w.name}</h3>
          </div>
        </div>
        <!-- Subject tags -->
        <p class="text-slate-500 dark:text-slate-400 text-xs font-semibold mb-4 leading-relaxed">${w.subjects}</p>
        <!-- Stats row -->
        <div class="flex items-center gap-4 mb-3">
          <span class="text-xs font-bold" style="color:#22c55e;">📚 ${w.activities} Activities</span>
          <span class="text-xs font-bold text-kivora-purple">🎮 ${w.games} Games</span>
          <span class="text-xs font-bold text-kivora-teal">🧩 ${w.quizzes} Quizzes</span>
        </div>
        <!-- Age range -->
        <div class="text-xs text-slate-400 font-semibold">${w.tag}</div>
      </div>
    </div>
  `).join('');
}

const PREVIEW_COUNT = 10;

function makeCard_game(g) {
  return `<div class="card-lift ${g.bg} dark:bg-slate-800 rounded-2xl p-4 shadow cursor-pointer border border-transparent hover:border-kivora-purple transition-all flex-shrink-0" style="width:160px" role="button" tabindex="0" aria-label="Play ${g.name}" onclick="launchGame('${g.id}')">
    <div class="text-4xl mb-3 text-center">${g.emoji}</div>
    <div class="font-display font-extrabold text-sm text-center text-slate-800 dark:text-white mb-2 leading-tight">${g.name}</div>
    <div class="flex items-center justify-between text-xs text-slate-500 font-semibold">
      <span>⭐ ${g.stars}</span><span>👦 ${g.players}</span>
    </div>
    <div class="mt-2 text-center"><span class="text-xs font-bold bg-kivora-purple/10 text-kivora-purple px-2 py-1 rounded-full">Age ${g.age}</span></div>
  </div>`;
}

function scrollRow(id, dir) {
  const el = document.getElementById(id);
  if (el) el.scrollBy({ left: dir * 600, behavior: 'smooth' });
}

// Print-and-colour packs surfaced as game cards under the Creative filter —
// these open a real printable PDF (via openPrintable) instead of the quiz engine.
const PRINTABLE_GAME_CARDS = [
  { key: 'col_kivi_poses', name: 'Colour: Kivi Poses',     emoji: '🦊', bg: 'bg-orange-50 dark:bg-orange-900/20' },
  { key: 'col_mandalas',   name: 'Colour: Mandalas',       emoji: '🌀', bg: 'bg-purple-50 dark:bg-purple-900/20' },
  { key: 'col_science',    name: 'Colour: Science Scenes', emoji: '🔬', bg: 'bg-teal-50 dark:bg-teal-900/20' },
  { key: 'col_ocean',      name: 'Colour: Ocean Life',     emoji: '🐬', bg: 'bg-blue-50 dark:bg-blue-900/20' },
];

function makeCard_printableGame(p) {
  return `<div class="card-lift ${p.bg} dark:bg-slate-800 rounded-2xl p-4 shadow cursor-pointer border border-transparent hover:border-kivora-purple transition-all flex-shrink-0" style="width:160px" role="button" tabindex="0" aria-label="Print and colour ${p.name}" onclick="openPrintable('${p.key}')">
    <div class="text-4xl mb-3 text-center">${p.emoji}</div>
    <div class="font-display font-extrabold text-sm text-center text-slate-800 dark:text-white mb-2 leading-tight">${p.name}</div>
    <div class="mt-2 text-center"><span class="text-xs font-bold bg-kivora-purple/10 text-kivora-purple px-2 py-1 rounded-full">🖨️ Print &amp; Colour</span></div>
  </div>`;
}

function renderGames(filter='all') {
  const el = document.getElementById('gamesGrid');
  const btn = document.getElementById('gamesShowMore');
  const data = filter === 'all' ? GAMES : GAMES.filter(g => g.tag === filter);
  const extra = (filter === 'all' || filter === 'creative') ? PRINTABLE_GAME_CARDS : [];
  el.innerHTML = extra.map(makeCard_printableGame).join('') + data.slice(0, PREVIEW_COUNT).map(makeCard_game).join('');
  el.dataset.filter = filter;
  el.dataset.shown = PREVIEW_COUNT;
  if (btn) btn.style.display = data.length > PREVIEW_COUNT ? '' : 'none';
}

function showMoreGames() {
  const el = document.getElementById('gamesGrid');
  const btn = document.getElementById('gamesShowMore');
  const filter = el.dataset.filter || 'all';
  const data = filter === 'all' ? GAMES : GAMES.filter(g => g.tag === filter);
  const shown = parseInt(el.dataset.shown) || PREVIEW_COUNT;
  const next = shown + PREVIEW_COUNT;
  el.innerHTML += data.slice(shown, next).map(makeCard_game).join('');
  el.dataset.shown = next;
  if (next >= data.length && btn) btn.style.display = 'none';
}

function makeCard_story(s) {
  return `<div class="card-lift bg-white dark:bg-slate-800 rounded-2xl overflow-hidden shadow cursor-pointer group hover:shadow-xl flex-shrink-0" style="width:180px" role="button" tabindex="0" aria-label="Read ${s.title}" onclick="openStory('${s.id}')">
    <div style="background:linear-gradient(135deg,${s.color},${s.color}cc)" class="h-28 flex items-center justify-center text-5xl group-hover:scale-110 transition-transform duration-300">${s.cover}</div>
    <div class="p-4">
      <div class="font-display font-extrabold text-sm text-slate-800 dark:text-white mb-2 leading-tight line-clamp-2">${s.title}</div>
      <div class="flex items-center justify-between text-xs font-semibold">
        <span class="text-slate-400">${s.pages.length} pages</span>
        <span class="bg-purple-100 text-purple-700 px-2 py-1 rounded-full">${s.age}</span>
      </div>
    </div>
  </div>`;
}

function renderStories() {
  const el = document.getElementById('storiesGrid');
  if(!el) return;
  const btn = document.getElementById('storiesShowMore');
  el.innerHTML = STORY_LIBRARY.slice(0, PREVIEW_COUNT).map(makeCard_story).join('');
  el.dataset.shown = PREVIEW_COUNT;
  if (btn) btn.style.display = STORY_LIBRARY.length > PREVIEW_COUNT ? '' : 'none';
}

function showMoreStories() {
  const el = document.getElementById('storiesGrid');
  const btn = document.getElementById('storiesShowMore');
  const shown = parseInt(el.dataset.shown) || PREVIEW_COUNT;
  const next = shown + PREVIEW_COUNT;
  el.innerHTML += STORY_LIBRARY.slice(shown, next).map(makeCard_story).join('');
  el.dataset.shown = next;
  if (next >= STORY_LIBRARY.length && btn) btn.style.display = 'none';
}

const VIDEO_COLORS = {Science:'bg-teal-100 text-teal-700',Reading:'bg-pink-100 text-pink-700',Math:'bg-blue-100 text-blue-700',Social:'bg-yellow-100 text-yellow-700',Writing:'bg-purple-100 text-purple-700'};

function makeCard_video(v) {
  return `<div class="card-lift bg-white dark:bg-slate-800 rounded-2xl overflow-hidden shadow cursor-pointer group hover:shadow-xl flex-shrink-0" style="width:200px" role="button" tabindex="0" aria-label="Watch ${v.title}" onclick="openVideoLesson('${v.id}')">
    <div class="bg-slate-100 dark:bg-slate-700 h-32 flex items-center justify-center text-6xl relative group-hover:scale-105 transition-transform duration-300">
      ${v.emoji}
      <div class="absolute inset-0 flex items-center justify-center bg-black/0 group-hover:bg-black/10 transition-colors rounded-t-2xl">
        <div class="w-10 h-10 bg-white/90 rounded-full flex items-center justify-center text-kivora-purple font-extrabold text-lg shadow opacity-0 group-hover:opacity-100 transition-opacity">▶</div>
      </div>
    </div>
    <div class="p-4">
      <div class="font-display font-extrabold text-sm text-slate-800 dark:text-white mb-2 leading-tight">${v.title}</div>
      <div class="flex items-center justify-between text-xs font-semibold">
        <span class="text-slate-400">⏱ ${v.duration}</span>
        <span class="${VIDEO_COLORS[v.subject] || 'bg-slate-100 text-slate-700'} px-2 py-1 rounded-full">${v.subject}</span>
      </div>
    </div>
  </div>`;
}

function renderVideos() {
  const el = document.getElementById('videosGrid');
  const btn = document.getElementById('videosShowMore');
  el.innerHTML = VIDEO_LESSONS.slice(0, PREVIEW_COUNT).map(makeCard_video).join('');
  el.dataset.shown = PREVIEW_COUNT;
  if (btn) btn.style.display = VIDEO_LESSONS.length > PREVIEW_COUNT ? '' : 'none';
}

function showMoreVideos() {
  const el = document.getElementById('videosGrid');
  const btn = document.getElementById('videosShowMore');
  const shown = parseInt(el.dataset.shown) || PREVIEW_COUNT;
  const next = shown + PREVIEW_COUNT;
  el.innerHTML += VIDEO_LESSONS.slice(shown, next).map(makeCard_video).join('');
  el.dataset.shown = next;
  if (next >= VIDEO_LESSONS.length && btn) btn.style.display = 'none';
}

