// ────────────────────────────────────────────────
function subscribeNewsletter() {
  const email = document.getElementById('newsletterEmail').value;
  const msg = document.getElementById('newsletterMsg');
  if (email && email.includes('@')) {
    msg.classList.remove('hidden');
    document.getElementById('newsletterEmail').value = '';
    document.getElementById('newsletterEmail').disabled = true;
  } else {
    document.getElementById('newsletterEmail').classList.add('border-red-400');
    setTimeout(() => document.getElementById('newsletterEmail').classList.remove('border-red-400'), 2000);
  }
}

// Allow Enter key in newsletter
document.getElementById('newsletterEmail').addEventListener('keydown', (e) => {
  if (e.key === 'Enter') subscribeNewsletter();
});

