const sections = document.querySelectorAll('section[id]');
const navLinks = document.querySelectorAll('header .nav-link');
window.addEventListener('scroll', () => {
  let current = '';
  sections.forEach(s => {
    if (window.scrollY >= s.offsetTop - 80) current = s.id;
  });
  navLinks.forEach(a => {
    a.classList.toggle('text-kivora-purple', a.getAttribute('href') === '#'+current);
    a.classList.toggle('font-extrabold', a.getAttribute('href') === '#'+current);
  });
}, { passive: true });

