function launchGame(gameId){
  const act = GAME_ACTIVITIES.find(g => g.code === gameId);
  if(!act) return;
  window._kivoraGameSource = 'games';
  spaNavigate('player');
  const tb = document.querySelector('.tabbar');
  if(tb) tb.style.display = 'none';
  setTimeout(() => {
    if(typeof launchActivity === 'function') launchActivity(act);
  }, 90);
}


