function downloadPrintable(packKey){
  const pack = PRINTABLE_PACKS[packKey];
  if(!pack) return;
  const a = document.createElement('a');
  a.href = pack.data;
  a.download = pack.filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

