function _dataUriToBlobUrl(dataUri){
  // Converts a base64 data: URI to a Blob object URL. Browsers throttle or
  // block window.open() on large data: URIs (needs a manual refresh), but
  // open reliably on blob: URLs.
  try {
    const comma = dataUri.indexOf(',');
    const meta = dataUri.slice(5, comma); // e.g. "application/pdf;base64"
    const mime = meta.split(';')[0] || 'application/pdf';
    const b64 = dataUri.slice(comma + 1);
    const bin = atob(b64);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    const blob = new Blob([bytes], { type: mime });
    return URL.createObjectURL(blob);
  } catch(e) { return dataUri; }
}

function openPrintable(packKey){
  const pack = PRINTABLE_PACKS[packKey];
  if(pack){
    const url = _dataUriToBlobUrl(pack.data);
    const win = window.open(url, '_blank');
    // Revoke the blob URL later so the tab has time to load it
    setTimeout(function(){ try { URL.revokeObjectURL(url); } catch(e){} }, 60000);
    if(!win){ // popup blocked — fall back to a download link
      const a = document.createElement('a');
      a.href = url; a.download = packKey + '.pdf'; document.body.appendChild(a); a.click(); a.remove();
    }
    return;
  }
  const file = PRINTABLE_FILES[packKey];
  if(file){
    // Open the tab immediately (within the click gesture) so popup blockers allow it,
    // then verify the file actually exists before letting it load — falls back to a
    // toast instead of a dead/blank tab when the PDF hasn't been uploaded yet.
    const win = window.open('', '_blank');
    fetch(file.url, { method: 'HEAD' }).then(function(res){
      if(res.ok){
        if(win) win.location = file.url; else window.open(file.url, '_blank');
      } else {
        if(win) win.close();
        showToast('🖨️ This printable is being finalised — check back soon!');
      }
    }).catch(function(){
      if(win) win.close();
      showToast('🖨️ This printable is being finalised — check back soon!');
    });
    return;
  }
  showToast('🖨️ This printable is being finalised — check back soon!');
}

const SPA_PAGES = new Set([
  'home','player','worlds','activities','games','stories','videos','coloring',
  'printables','crafts','special-needs','paths','pricing','about',
  'teachers','parents','blog','careers','privacy','terms','compliance'
]);

function openWorldInPlayer(num){
  window._kivoraGameSource = null;
  const tb = document.querySelector('.tabbar');
  if(tb) tb.style.display = '';
  const NUM_TO_WORLD_SLUG={
    1:'alphabet-island',2:'math-mountain',3:'story-cove',4:'creativity-kingdom',
    5:'science-safari',6:'life-skills-village',7:'coding-city',8:'music-meadow',9:'brain-game-galaxy'
  };
  const slug=NUM_TO_WORLD_SLUG[num]||'alphabet-island';
  window._kivoraPendingWorld=slug;
  spaNavigate('player');
  // If the player app is already past its start gate (returning visit), switch tab directly.
  // If the gate is still showing, buildUI() (triggered by tapping the gate) will consume
  // window._kivoraPendingWorld instead — see buildUI().
  setTimeout(()=>{
    const gate=document.getElementById('gate');
    const appShown = gate && gate.style.display==='none';
    if(appShown && typeof switchTab==='function'){
      switchTab(slug);
      window._kivoraPendingWorld=null;
    }
  }, 60);
}

function spaNavigate(slug, hash){
  if(!SPA_PAGES.has(slug)) slug='home';
  document.querySelectorAll('.spa-page').forEach(s=>{ s.style.display='none'; });
  const target=document.getElementById('spa-'+slug);
  if(target) target.style.display='block';
  window.scrollTo(0,0);
  if(history.pushState){ try{ history.pushState({spa:slug}, '', '#'+(slug==='home'?'':slug)); }catch(e){ /* sandboxed preview (e.g. about:srcdoc) — navigation still works, just no URL update */ } }
  document.querySelectorAll('.mobile-menu-open').forEach(m=>m.classList.remove('mobile-menu-open'));
  const mm=document.getElementById('mobileMenu'); if(mm) mm.classList.add('hidden');
  if(hash){
    setTimeout(()=>{
      const el=document.getElementById(hash);
      if(el) el.scrollIntoView({behavior:'smooth', block:'start'});
    },80);
  }
}

function _spaResolveHref(href){
  // strips leading ./ and trailing .html, separates any #hash
  const m=href.match(/^\.?\/?([\w-]+)\.html(?:#([\w-]+))?$/);
  if(!m) return null;
  let slug=m[1];
  if(slug==='kivora-activity-player') slug='player';
  return { slug, hash:m[2]||null };
}

const HOME_TEASER_ANCHORS = new Set(['home','learn','games','stories','videos','printables','parents','teachers','pricing']);

document.addEventListener('click', function(e){
  const a=e.target.closest('a[href]');
  if(!a) return;
  const href=a.getAttribute('href');
  if(!href) return;

  // Bare #anchor links to homepage teaser sections (nav bar) — ensure spa-home is visible first
  if(href.startsWith('#')){
    const anchorId=href.slice(1);
    if(HOME_TEASER_ANCHORS.has(anchorId)){
      e.preventDefault();
      const homeSection=document.getElementById('spa-home');
      const alreadyHome = homeSection && homeSection.style.display!=='none';
      if(!alreadyHome) spaNavigate('home');
      setTimeout(()=>{
        const target=document.getElementById(anchorId);
        if(target) target.scrollIntoView({behavior:'smooth', block:'start'});
        else window.scrollTo({top:0, behavior:'smooth'});
      }, alreadyHome ? 0 : 80);
    }
    return; // other "#" links (modal triggers etc.) fall through untouched
  }

  const resolved=_spaResolveHref(href);
  if(resolved && SPA_PAGES.has(resolved.slug)){
    e.preventDefault();
    spaNavigate(resolved.slug, resolved.hash);
  }
  // kivora-activity-player.html links now route to the embedded #spa-player section too.
  // mailto:, http(s):, and "#" (modal trigger) links fall through untouched.
});

window.addEventListener('popstate', function(e){
  const slug=(e.state && e.state.spa) || (location.hash ? location.hash.slice(1) : 'home');
  spaNavigate(slug);
});

// Shared stub filter functions (identical across activities/games/stories pages originally)
function filterContent(v,t){ console.log('filter',t,v); }
function filterPosts(cat){ console.log('filter:',cat); }

// Initial route on page load — supports deep-linking via #slug
(function spaInit(){
  const initial = location.hash ? location.hash.slice(1) : 'home';
  if(SPA_PAGES.has(initial) && initial!=='home'){
    document.querySelectorAll('.spa-page').forEach(s=>{ s.style.display='none'; });
    const target=document.getElementById('spa-'+initial);
    if(target) target.style.display='block';
  }
  // If going to player and a child already exists, pre-fill name and auto-start
  if(initial === 'player'){
    document.addEventListener('DOMContentLoaded', function(){
      const child = getActiveChild() || (getChildren()||[])[0];
      if(child){
        const nameEl = document.getElementById('gateChildName');
        if(nameEl) nameEl.value = child.name;
        // Auto-start after a brief moment so activities.js has loaded
        setTimeout(function(){
          const gateEl = document.getElementById('gate');
          if(gateEl) gateEl.style.display = 'none';
          if(typeof unlockAndStart === 'function') unlockAndStart();
        }, 300);
      }
    });
  }
})();
