function buildAvatarPicker(){
  const el = document.getElementById('avatarPicker');
  if(!el) return;
  el.innerHTML = AVATARS.map(av=>`<button type="button" onclick="selectAvatar('${av}',this)"
    style="width:44px;height:44px;font-size:1.5rem;border-radius:12px;border:2px solid #e2e8f0;background:#f8fafc;cursor:pointer;transition:all .15s"
    class="avatar-btn">${av}</button>`).join('');
  selectAvatar(_selectedAvatar, el.querySelector('button'));
}

function selectAvatar(av, btn){
  _selectedAvatar = av;
  document.querySelectorAll('.avatar-btn').forEach(b=>{
    b.style.borderColor='#e2e8f0'; b.style.background='#f8fafc'; b.style.transform='scale(1)';
  });
  if(btn){ btn.style.borderColor='#7C3AED'; btn.style.background='#ede9fe'; btn.style.transform='scale(1.15)'; }
}

function buildExistingChildren(){
  const kids = getChildren();
  const panel = document.getElementById('existing-children-panel');
  const list  = document.getElementById('existing-children-list');
  const form  = document.getElementById('new-child-form');
  if(!panel||!list) return;
  if(kids.length===0){ panel.style.display='none'; form.style.display='block'; return; }
  list.innerHTML = kids.map(c=>{
    const p = getChildProgress(c.id);
    return `<button type="button" onclick="loginAsChild('${c.id}')"
      style="display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:14px;border:2px solid #e2e8f0;background:#f8fafc;cursor:pointer;font-family:inherit;width:100%;transition:all .2s"
      onmouseover="this.style.borderColor='#7C3AED';this.style.background='#ede9fe'"
      onmouseout="this.style.borderColor='#e2e8f0';this.style.background='#f8fafc'">
      <span style="font-size:2rem">${c.avatar}</span>
      <div style="text-align:left">
        <div style="font-weight:800;font-size:.95rem;color:#1e293b">${c.name}</div>
        <div style="font-size:.78rem;font-weight:600;color:#64748b">${c.grade} · ⭐${p.xp} XP · ✅${p.completed} done</div>
      </div>
      <span style="margin-left:auto;color:#7C3AED;font-size:1.2rem">→</span>
    </button>`;
  }).join('');
  panel.style.display='block';
  form.style.display='none';
}

function loginAsChild(id){
  _lsSet('kivora_active_child', id);
  const child = getChildren().find(c=>c.id===id);
  if(child){ updateNavAuth(child); showChildDashboard(child); }
}

function startLearning(){
  const nameEl  = document.getElementById('childNameInput');
  const gradeEl = document.getElementById('childGradeInput');
  const errEl   = document.getElementById('auth-error-msg');
  const name    = (nameEl?.value||'').trim();
  if(!name){ errEl.textContent='Please enter a name!'; errEl.style.display='block'; nameEl.focus(); return; }
  errEl.style.display='none';
  const child = { id:_uid(), name, avatar:_selectedAvatar, grade:gradeEl?.value||'kindergarten', createdAt:Date.now() };
  const kids  = getChildren();
  kids.push(child);
  _lsSet('kivora_children', kids);
  _lsSet('kivora_active_child', child.id);
  _lsSet('kivora_session', { name, createdAt:Date.now() });
  updateNavAuth(child);
  showChildDashboard(child);
}

function googleSignIn(errorMsgId, btnId, label) {
  var btn = document.getElementById(btnId);
  var msg = document.getElementById(errorMsgId);
  if (btn && btn.disabled) return;
  if (btn) { btn.disabled = true; btn.textContent = 'Opening Google…'; }
  if (msg) msg.style.display = 'none';
  kivoraFirebase.signInWithGoogle().catch(function(e) {
    if (btn) { btn.disabled = false; btn.innerHTML = '<span style="font-size:1.2rem">G</span> ' + label; }
    if (e && (e.code === 'auth/cancelled-popup-request' || e.code === 'auth/popup-closed-by-user')) return;
    var m = (e && e.message) ? e.message : 'Google sign-in failed — please try again.';
    if (msg) { msg.textContent = m; msg.style.display = 'block'; }
  });
}

function emailSignIn() {
  var e = document.getElementById('loginEmail');
  var p = document.getElementById('loginPassword');
  var msg = document.getElementById('auth-error-msg');
  var btn = document.getElementById('emailSignInBtn');
  if (msg) msg.style.display = 'none';
  if (!e.value) { if(msg){msg.textContent='Please enter your email address';msg.style.display='block';} e.focus(); return; }
  if (!p.value) { if(msg){msg.textContent='Please enter your password';msg.style.display='block';} p.focus(); return; }
  if (btn) { btn.disabled = true; btn.textContent = 'Signing in…'; }
  kivoraFirebase.signInWithEmail(e.value, p.value).catch(function(err) {
    if (btn) { btn.disabled = false; btn.textContent = 'Sign In'; }
    var m = (err && err.message) ? err.message : 'Sign-in failed — please check your email and password.';
    if (m.indexOf('user-not-found') > -1 || m.indexOf('wrong-password') > -1 || m.indexOf('invalid-credential') > -1)
      m = 'Incorrect email or password — please try again.';
    if (m.indexOf('too-many-requests') > -1) m = 'Too many attempts — please wait a moment and try again.';
    if (msg) { msg.textContent = m; msg.style.display = 'block'; }
  });
}

function emailCreateAccount() {
  var e = document.getElementById('regEmail');
  var p = document.getElementById('regPassword');
  var msg = document.getElementById('reg-error-msg');
  var btn = document.getElementById('createAccountBtn');
  if (msg) msg.style.display = 'none';
  if (!e.value) { if(msg){msg.textContent='Please enter an email address';msg.style.display='block';} e.focus(); return; }
  if (p.value.length < 6) { if(msg){msg.textContent='Password must be at least 6 characters';msg.style.display='block';} p.focus(); return; }
  if (btn) { btn.disabled = true; btn.textContent = 'Creating account…'; }
  kivoraFirebase.createAccount(e.value, p.value).catch(function(err) {
    if (btn) { btn.disabled = false; btn.textContent = 'Create Account'; }
    var m = (err && err.message) ? err.message : 'Account creation failed — please try again.';
    if (m.indexOf('email-already-in-use') > -1) m = 'That email is already registered — try signing in instead.';
    if (m.indexOf('invalid-email') > -1) m = 'Please enter a valid email address.';
    if (m.indexOf('not available') > -1) m = 'Service unavailable — please check your internet connection.';
    if (msg) { msg.textContent = m; msg.style.display = 'block'; }
  });
}

// Called from the #player gate screen — quick anonymous start with optional name
function gateStart(){
  const nameEl = document.getElementById('gateChildName');
  const name   = (nameEl?.value||'').trim() || 'Learner';
  // Reuse existing child session if one already exists
  const existing = getChildren();
  let child = existing[existing.length - 1];
  if (!child) {
    child = { id:_uid(), name, avatar:'🦊', grade:'kindergarten', createdAt:Date.now() };
    existing.push(child);
    _lsSet('kivora_children', existing);
    _lsSet('kivora_active_child', child.id);
    _lsSet('kivora_session', { name, createdAt:Date.now() });
  }
  if (typeof unlockAndStart === 'function') unlockAndStart();
}

// Called from parent/child dashboard — skip gate if child already set
function startLearningAsChild(childId){
  const kids = getChildren();
  const child = childId ? kids.find(c=>c.id===childId) : (getActiveChild() || kids[kids.length-1]);
  closePageModal();
  if(child){
    _lsSet('kivora_active_child', child.id);
    _lsSet('kivora_session', { name: child.name, createdAt: Date.now() });
    updateNavAuth(child);
    // Hide gate immediately so it never flashes
    const gateEl = document.getElementById('gate');
    if(gateEl) gateEl.style.display = 'none';
    spaNavigate('player');
    if(typeof unlockAndStart === 'function') unlockAndStart();
  } else {
    spaNavigate('player');
  }
}

function showChildDashboard(child){
  _lsSet('kivora_active_child', child.id);
  _lsSet('kivora_session', { name: child.name, createdAt: Date.now() });
  const p = getChildProgress(child.id);
  const el = id => document.getElementById(id);
  if(el('dashAvatar')) el('dashAvatar').textContent = child.avatar;
  if(el('dashName'))   el('dashName').textContent   = 'Hi '+child.name+'! 👋';
  if(el('dashXP'))     el('dashXP').textContent     = '⭐ '+p.xp+' XP';
  if(el('dashCoins'))  el('dashCoins').textContent  = '🪙 '+p.coins+' Coins';
  if(el('dashDone'))   el('dashDone').textContent   = '✅ '+p.completed+' Done';
  openPage('child-dashboard');
}

function showParentDashboard(){
  const list = document.getElementById('parent-child-list');
  if(!list) return;
  const kids = getChildren();
  if(kids.length===0){
    list.innerHTML='<p style="text-align:center;color:#64748b;font-size:.88rem;padding:16px 0">No children added yet.</p>';
  } else {
      list.innerHTML = kids.map(c=>{
      const p = getChildProgress(c.id);
      return `<div style="background:#f8fafc;border-radius:14px;padding:14px 16px;display:flex;align-items:center;gap:12px">
        <span style="font-size:2rem">${c.avatar}</span>
        <div style="flex:1">
          <div style="font-weight:800;color:#1e293b">${c.name} <span style="font-size:.75rem;font-weight:600;color:#94a3b8">${c.grade}</span></div>
          <div style="font-size:.8rem;font-weight:600;color:#64748b;margin-top:2px">⭐ ${p.xp} XP &nbsp;·&nbsp; ✅ ${p.completed} activities</div>
        </div>
        <button onclick="startLearningAsChild('${c.id}')" style="padding:6px 14px;border-radius:10px;border:none;background:#7C3AED;color:#fff;font-family:inherit;font-size:.8rem;font-weight:700;cursor:pointer">▶ Learn</button>
      </div>`;
    }).join('');
  }
}

// ── TEACHER / CLASS DASHBOARD ──────────────────────────────────────
function getClasses(){ return _lsGet('kivora_classes') || []; }
function getActiveClass(){
  const id = _lsGet('kivora_active_class');
  const classes = getClasses();
  return classes.find(c=>c.id===id) || classes[0] || null;
}

function buildExistingClasses(){
  const classes = getClasses();
  const panel = document.getElementById('existing-classes-panel');
  const list  = document.getElementById('existing-classes-list');
  const form  = document.getElementById('new-class-form');
  if(!panel||!list) return;
  if(classes.length===0){ panel.style.display='none'; form.style.display='block'; return; }
  list.innerHTML = classes.map(c=>`<button type="button" onclick="loginAsClass('${c.id}')"
    style="display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:14px;border:2px solid #e2e8f0;background:#f8fafc;cursor:pointer;font-family:inherit;width:100%;transition:all .2s"
    onmouseover="this.style.borderColor='#0EA5E9';this.style.background='#e0f2fe'"
    onmouseout="this.style.borderColor='#e2e8f0';this.style.background='#f8fafc'">
    <span style="font-size:2rem">🏫</span>
    <div style="text-align:left">
      <div style="font-weight:800;font-size:.95rem;color:#1e293b">${c.name}</div>
      <div style="font-size:.78rem;font-weight:600;color:#64748b">${c.teacherName} · ${c.students.length} student${c.students.length===1?'':'s'}</div>
    </div>
    <span style="margin-left:auto;color:#0EA5E9;font-size:1.2rem">→</span>
  </button>`).join('');
  panel.style.display='block';
  form.style.display='none';
}

function loginAsClass(id){
  _lsSet('kivora_active_class', id);
  showTeacherDashboard();
  openPage('teacher-dashboard');
}

function startTeacherClass(){
  const teacherEl = document.getElementById('teacherNameInput');
  const classEl   = document.getElementById('teacherClassInput');
  const errEl     = document.getElementById('teacher-error-msg');
  const teacherName = (teacherEl?.value||'').trim();
  const className   = (classEl?.value||'').trim();
  if(!teacherName || !className){ errEl.textContent='Please enter your name and a class name!'; errEl.style.display='block'; return; }
  errEl.style.display='none';
  const cls = { id:_uid(), teacherName, name:className, students:[], createdAt:Date.now() };
  const classes = getClasses();
  classes.push(cls);
  _lsSet('kivora_classes', classes);
  _lsSet('kivora_active_class', cls.id);
  showTeacherDashboard();
  openPage('teacher-dashboard');
}

function addStudentPrompt(){
  const name = (prompt('Student name:')||'').trim();
  if(!name) return;
  const cls = getActiveClass();
  if(!cls) return;
  const student = { id:_uid(), name, grade:'kindergarten', joinedAt:Date.now() };
  cls.students.push(student);
  _lsSet('kivora_classes', getClasses().map(c=>c.id===cls.id?cls:c));
  // Also register student in kivora_children so startLearningAsChild can find them
  const kids = getChildren();
  if(!kids.find(k=>k.id===student.id)){
    kids.push({ id:student.id, name:student.name, avatar:'🎓', grade:student.grade, createdAt:student.joinedAt });
    _lsSet('kivora_children', kids);
  }
  showTeacherDashboard();
}

function showTeacherDashboard(){
  const cls    = getActiveClass();
  const nameEl = document.getElementById('teacherClassName');
  const statsEl= document.getElementById('teacher-class-stats');
  const list   = document.getElementById('teacher-student-list');
  if(!list) return;
  if(!cls){
    if(nameEl) nameEl.textContent = 'No Class Yet';
    if(statsEl) statsEl.textContent = 'Create a class to get started';
    list.innerHTML = '<p style="text-align:center;color:#64748b;font-size:.88rem;padding:16px 0">No class yet. Create one to add students.</p>';
    return;
  }
  if(nameEl) nameEl.textContent = cls.name;
  const ranked = cls.students
    .map(s => ({ ...s, progress: getChildProgress(s.id) }))
    .sort((a,b) => b.progress.xp - a.progress.xp);
  if(ranked.length===0){
    list.innerHTML = '<p style="text-align:center;color:#64748b;font-size:.88rem;padding:16px 0">No students yet. Add your first student!</p>';
  } else {
    list.innerHTML = ranked.map((s,i)=>`<div style="background:#f8fafc;border-radius:14px;padding:14px 16px;display:flex;align-items:center;gap:12px">
      <span style="font-weight:800;color:#94a3b8;width:20px;text-align:center">${i+1}</span>
      <div style="flex:1">
        <div style="font-weight:800;color:#1e293b">${s.name} <span style="font-size:.75rem;font-weight:600;color:#94a3b8">${s.grade}</span></div>
        <div style="font-size:.8rem;font-weight:600;color:#64748b;margin-top:2px">⭐ ${s.progress.xp} XP &nbsp;·&nbsp; ✅ ${s.progress.completed} activities</div>
      </div>
      <button onclick="startLearningAsChild('${s.id}')" style="padding:6px 14px;border-radius:10px;border:none;background:#0EA5E9;color:#fff;font-family:inherit;font-size:.8rem;font-weight:700;cursor:pointer">▶ Learn</button>
    </div>`).join('');
  }
  if(statsEl){
    const totalXP   = ranked.reduce((s,r)=>s+r.progress.xp,0);
    const totalDone = ranked.reduce((s,r)=>s+r.progress.completed,0);
    statsEl.textContent = `${ranked.length} student${ranked.length===1?'':'s'} · ⭐ ${totalXP} XP total · ✅ ${totalDone} activities completed`;
  }
}

// Override handleLogin to use our local system
function handleLogin(e){ if(e&&e.preventDefault) e.preventDefault(); openPage('login'); }
function handleRegisterComplete(){ startLearning(); }
function regGoStep(n){ if(n===3) startLearning(); }

// On page load — restore active child session
document.addEventListener('DOMContentLoaded', function(){
  const child = getActiveChild();
  if(child) updateNavAuth(child);
});
/* ═══════════════════════════════════════ */
  function openPage(pageName) {
  // register page now has its own content (Google + email sign-up)
  var modal = document.getElementById('pageModal');
  if(modal){ modal.classList.add('modal-open'); modal.style.display='block'; }
  document.body.style.overflow = 'hidden';
  document.querySelectorAll('.modal-page').forEach(function(p){
    p.classList.remove('active'); p.style.display='none';
  });
  var target = document.getElementById('page-' + pageName);
  if (target){ target.classList.add('active'); target.style.display='block'; }
  if(modal) modal.scrollTop = 0;
  if (pageName === 'login'){ if(typeof buildAvatarPicker==='function') buildAvatarPicker(); if(typeof buildExistingChildren==='function') buildExistingChildren(); }
  if (pageName === 'parent-dashboard' && typeof showParentDashboard==='function') showParentDashboard();
  if (pageName === 'teacher-login' && typeof buildExistingClasses==='function') buildExistingClasses();
  if (pageName === 'teacher-dashboard' && typeof showTeacherDashboard==='function') showTeacherDashboard();
}
function closePageModal() {
  var modal = document.getElementById('pageModal');
  if (modal){ modal.classList.remove('modal-open'); modal.style.display='none'; }
  document.body.style.overflow = '';
  document.querySelectorAll('.modal-page').forEach(function(p){ p.classList.remove('active'); p.style.display='none'; });
}
