// ── BILLING TOGGLE ────────────────────────────────────────────────
let isAnnual = false;
function toggleBilling() {
  isAnnual = !isAnnual;
  const thumb = document.getElementById('billingThumb');
  const monthly = document.getElementById('lblMonthly');
  const annual = document.getElementById('lblAnnual');
  if (thumb) thumb.style.transform = isAnnual ? 'translateX(24px)' : 'translateX(0)';
  const toggle = document.getElementById('billingToggle');
  if (toggle) toggle.setAttribute('aria-checked', String(isAnnual));
  if (monthly) { monthly.style.fontWeight = isAnnual ? '700' : '800'; monthly.style.color = isAnnual ? '#94a3b8' : '#1e293b'; }
  if (annual) { annual.style.color = isAnnual ? '#1e293b' : '#94a3b8'; }
  document.querySelectorAll('.price-tag').forEach(el => {
    const val = isAnnual ? el.getAttribute('data-annual') : el.getAttribute('data-monthly');
    el.textContent = '$' + parseFloat(val).toFixed(2);
  });
}

document.addEventListener('DOMContentLoaded', () => {
  renderWorlds();
  renderGames();
  renderStories();
  renderVideos();
  renderPrintables();
  renderTestimonials();
  renderBlog();
  setTimeout(reObserve, 200);
  // Modal listeners — runs after full DOM (incl. modal HTML) is ready
  var closeBtn = document.getElementById('closeModal');
  var modal    = document.getElementById('pageModal');
  if (closeBtn) closeBtn.addEventListener('click', closePageModal);
  if (modal)    modal.addEventListener('click', function(e){ if (e.target === this) closePageModal(); });
  document.addEventListener('keydown', function(e){ if (e.key === 'Escape') closePageModal(); });
});
